/* Renders the app's Lucide icons into anti-aliased 8-bit alpha bitmaps and writes them as C source.
 * Usage: gen_icons <lucide.ttf> <lucide_icons.txt> <out.h> <out.c>
 * Run via `make icons`; the generated files are committed so device builds don't need this tool. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define STB_TRUETYPE_IMPLEMENTATION
#include "../../third_party/stb/stb_truetype.h"

static const int sizes[] = { 32, 44, 56, 72 };
#define NSIZES (int)(sizeof sizes / sizeof sizes[0])

int main(int argc, char **argv) {
    if (argc != 5) { fprintf(stderr, "usage: gen_icons font.ttf list.txt out.h out.c\n"); return 1; }
    FILE *fp = fopen(argv[1], "rb");
    if (!fp) { perror(argv[1]); return 1; }
    fseek(fp, 0, SEEK_END);
    long n = ftell(fp);
    rewind(fp);
    unsigned char *ttf = malloc(n);
    if (fread(ttf, 1, n, fp) != (size_t)n) return 1;
    fclose(fp);
    stbtt_fontinfo font;
    stbtt_InitFont(&font, ttf, stbtt_GetFontOffsetForIndex(ttf, 0));

    char ids[64][32];
    unsigned cps[64];
    int count = 0;
    FILE *list = fopen(argv[2], "r");
    if (!list) { perror(argv[2]); return 1; }
    char line[256];
    while (fgets(line, sizeof line, list) && count < 64) {
        char name[64];
        if (line[0] == '#') continue;
        if (sscanf(line, "%31s %63s %x", ids[count], name, &cps[count]) == 3) count++;
    }
    fclose(list);

    FILE *h = fopen(argv[3], "w"), *c = fopen(argv[4], "w");
    fprintf(h, "/* Generated by tools/icons/gen_icons.c from Lucide (ISC license). Do not edit. */\n");
    fprintf(h, "#ifndef ICONS_DATA_H\n#define ICONS_DATA_H\n\n");
    fprintf(h, "typedef struct { int size; const unsigned char *alpha; } IconBitmap;\n\n");
    fprintf(h, "enum {\n");
    for (int i = 0; i < count; i++) fprintf(h, "    GI_%s,\n", ids[i]);
    fprintf(h, "    GI_COUNT\n};\n\n#define ICON_SIZES %d\n", NSIZES);
    fprintf(h, "/* Square bitmaps, smallest size first; alpha 0 = transparent, 255 = full ink. */\n");
    fprintf(h, "extern const IconBitmap icon_bitmaps[GI_COUNT][ICON_SIZES];\n\n#endif\n");

    fprintf(c, "/* Generated by tools/icons/gen_icons.c from Lucide (ISC license). Do not edit. */\n");
    fprintf(c, "#include \"icons_data.h\"\n\n");
    for (int i = 0; i < count; i++) {
        for (int s = 0; s < NSIZES; s++) {
            int N = sizes[s];
            unsigned char *canvas = calloc(N * N, 1);
            /* Lucide draws on a 24x24 grid that fills the em square. */
            float scale = stbtt_ScaleForMappingEmToPixels(&font, (float)N);
            int gw, gh, xo, yo;
            unsigned char *bmp = stbtt_GetCodepointBitmap(&font, scale, scale, (int)cps[i], &gw, &gh, &xo, &yo);
            if (!bmp || gw == 0) { fprintf(stderr, "glyph %s missing\n", ids[i]); return 1; }
            int ox = (N - gw) / 2, oy = (N - gh) / 2;
            for (int y = 0; y < gh; y++)
                for (int x = 0; x < gw; x++) {
                    int X = ox + x, Y = oy + y;
                    if (X >= 0 && Y >= 0 && X < N && Y < N) canvas[Y * N + X] = bmp[y * gw + x];
                }
            stbtt_FreeBitmap(bmp, NULL);
            fprintf(c, "static const unsigned char %s_%d[%d] = {", ids[i], N, N * N);
            for (int k = 0; k < N * N; k++) fprintf(c, "%s%u,", k % 32 ? "" : "\n    ", canvas[k]);
            fprintf(c, "\n};\n");
            free(canvas);
        }
    }
    fprintf(c, "\nconst IconBitmap icon_bitmaps[GI_COUNT][ICON_SIZES] = {\n");
    for (int i = 0; i < count; i++) {
        fprintf(c, "    {");
        for (int s = 0; s < NSIZES; s++) fprintf(c, " { %d, %s_%d },", sizes[s], ids[i], sizes[s]);
        fprintf(c, " },\n");
    }
    fprintf(c, "};\n");
    fclose(h);
    fclose(c);
    printf("generated %d icons x %d sizes\n", count, NSIZES);
    return 0;
}
